/*
 * 随机表图本地化兜底
 * 主脚本会请求 ./gif/TJ<n>.gif 或 ./png/TJ<n>.png（n 为 1~60 的随机数）。
 * 完整 120 张表图已镜像到 gif/ 与 png/ 目录；若目录缺失、以 file:// 打开
 * 或请求失败，则改用这里内嵌在网页中的表图，避免出现「加载失败」破图。
 */
(function () {
  'use strict';
  var BUILTIN = {
    gif: ["data:image/gif;base64,", "data:image/gif;base64,", "data:image/gif;base64,", "data:image/gif;base64,", "data:image/gif;base64,", "data:image/gif;base64,"],
    png: ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]
  };
  var realFetch = window.fetch.bind(window);
  var coverIndexOverride = null;
  var lastCoverIndex = null;

  // 换一张随机表图：生成新编号，再点一次当前格式按钮让主脚本重新加载封面。
  window.refreshRandomCover = function () {
    var active = document.querySelector('.format-btn.active');
    var fmt = active ? active.dataset.format : 'gif';
    var list = BUILTIN[fmt] || BUILTIN.gif;
    var n, tries = 0;
    do {
      n = Math.floor(Math.random() * 60) + 1;
      tries++;
    } while (tries < 20 && lastCoverIndex !== null &&
             (n % list.length) === (lastCoverIndex % list.length));
    lastCoverIndex = n;
    coverIndexOverride = n;
    var btn = document.querySelector('.format-btn[data-format="' + fmt + '"]');
    if (btn) btn.click();
  };

  window.fetch = function (input, init) {
    var url = typeof input === 'string' ? input : (input && input.url) || '';
    var m = /^\.?\/?(gif|png)\/TJ(\d+)\.(gif|png)$/.exec(url);
    if (!m) return realFetch(input, init);
    var n = coverIndexOverride !== null ? coverIndexOverride : parseInt(m[2], 10);
    coverIndexOverride = null;
    var list = BUILTIN[m[1]];
    var fallback = list[n % list.length];
    var path = './' + m[1] + '/TJ' + n + '.' + m[1];
    return realFetch(path, init).then(function (res) {
      return (res && res.ok) ? res : realFetch(fallback);
    }).catch(function () {
      return realFetch(fallback);
    });
  };
})();
